-- AIMS initial MySQL schema
-- Requires MySQL 8.0.16+ (enforced CHECK constraints, JSON columns, generated columns).
-- UUID values are generated by the application and stored as CHAR(36).
-- Safe to rerun for missing tables and current triggers. See README.md for schema evolution details.

CREATE DATABASE IF NOT EXISTS aims_db
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;
USE aims_db;

CREATE TABLE IF NOT EXISTS users (
    id              CHAR(36) NOT NULL,
    email           VARCHAR(254) NOT NULL,
    password_hash   TEXT NOT NULL,
    display_name    VARCHAR(160) NOT NULL,
    user_role       ENUM('admin', 'inventory_manager', 'staff', 'viewer') NOT NULL DEFAULT 'staff',
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at      TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    UNIQUE KEY users_email_uq (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inventory_categories (
    id              CHAR(36) NOT NULL,
    name            VARCHAR(120) NOT NULL,
    slug            VARCHAR(140) NOT NULL,
    description     TEXT,
    created_by      CHAR(36),
    created_at      TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at      TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    archived_at     TIMESTAMP(3) NULL,
    active_slug     VARCHAR(140) GENERATED ALWAYS AS
                    (CASE WHEN archived_at IS NULL THEN slug ELSE NULL END) STORED,
    PRIMARY KEY (id),
    UNIQUE KEY inventory_categories_active_slug_uq (active_slug),
    CONSTRAINT inventory_categories_created_by_fk
        FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inventory_schema_versions (
    id                  CHAR(36) NOT NULL,
    category_id         CHAR(36) NOT NULL,
    version_number      INT NOT NULL,
    status              VARCHAR(16) NOT NULL DEFAULT 'draft',
    source_prompt       TEXT,
    generation_method   VARCHAR(16) NOT NULL DEFAULT 'manual',
    created_by          CHAR(36),
    validated_by        CHAR(36),
    validation_notes    TEXT,
    display_labels      JSON NOT NULL DEFAULT (JSON_OBJECT()),
    created_at          TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    published_at        TIMESTAMP(3) NULL,
    active_category_id  CHAR(36) GENERATED ALWAYS AS
                        (CASE WHEN status = 'active' THEN category_id ELSE NULL END) STORED,
    PRIMARY KEY (id),
    UNIQUE KEY inventory_schema_category_version_uq (category_id, version_number),
    UNIQUE KEY inventory_schema_one_active_per_category_uq (active_category_id),
    UNIQUE KEY inventory_schema_id_category_uq (id, category_id),
    CONSTRAINT inventory_schema_version_number_chk CHECK (version_number > 0),
    CONSTRAINT inventory_schema_status_chk CHECK (status IN ('draft', 'active', 'retired')),
    CONSTRAINT inventory_schema_generation_method_chk
        CHECK (generation_method IN ('manual', 'nlp', 'llm')),
    CONSTRAINT inventory_schema_display_labels_chk CHECK (JSON_TYPE(display_labels) = 'OBJECT'),
    CONSTRAINT inventory_schema_published_at_chk CHECK (
        (status = 'draft' AND published_at IS NULL)
        OR (status IN ('active', 'retired') AND published_at IS NOT NULL)
    ),
    CONSTRAINT inventory_schema_category_fk
        FOREIGN KEY (category_id) REFERENCES inventory_categories(id) ON DELETE RESTRICT,
    CONSTRAINT inventory_schema_created_by_fk
        FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL,
    CONSTRAINT inventory_schema_validated_by_fk
        FOREIGN KEY (validated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Keep this schema script safe to rerun against databases created from earlier versions.
SET @aims_add_display_labels_column = IF(
    (SELECT COUNT(*) FROM information_schema.COLUMNS
     WHERE TABLE_SCHEMA = DATABASE()
       AND TABLE_NAME = 'inventory_schema_versions'
       AND COLUMN_NAME = 'display_labels') = 0,
    'ALTER TABLE inventory_schema_versions ADD COLUMN display_labels JSON NOT NULL DEFAULT (JSON_OBJECT()) AFTER validation_notes',
    'SELECT 1'
);
PREPARE aims_display_labels_column_stmt FROM @aims_add_display_labels_column;
EXECUTE aims_display_labels_column_stmt;
DEALLOCATE PREPARE aims_display_labels_column_stmt;

SET @aims_add_display_labels_check = IF(
    (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS
     WHERE CONSTRAINT_SCHEMA = DATABASE()
       AND TABLE_NAME = 'inventory_schema_versions'
       AND CONSTRAINT_NAME = 'inventory_schema_display_labels_chk') = 0,
    'ALTER TABLE inventory_schema_versions ADD CONSTRAINT inventory_schema_display_labels_chk CHECK (JSON_TYPE(display_labels) = ''OBJECT'')',
    'SELECT 1'
);
PREPARE aims_display_labels_check_stmt FROM @aims_add_display_labels_check;
EXECUTE aims_display_labels_check_stmt;
DEALLOCATE PREPARE aims_display_labels_check_stmt;

CREATE TABLE IF NOT EXISTS inventory_schema_fields (
    id                  CHAR(36) NOT NULL,
    schema_version_id   CHAR(36) NOT NULL,
    field_key           VARCHAR(63) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    label               VARCHAR(120) NOT NULL,
    data_type           VARCHAR(16) NOT NULL,
    is_required         BOOLEAN NOT NULL DEFAULT FALSE,
    is_searchable       BOOLEAN NOT NULL DEFAULT FALSE,
    options             JSON NOT NULL DEFAULT (JSON_ARRAY()),
    validation_rules    JSON NOT NULL DEFAULT (JSON_OBJECT()),
    display_order       INT NOT NULL DEFAULT 0,
    created_at          TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    UNIQUE KEY inventory_schema_field_key_uq (schema_version_id, field_key),
    CONSTRAINT inventory_schema_field_key_chk CHECK (field_key REGEXP '^[a-z][a-z0-9_]{0,62}$'),
    CONSTRAINT inventory_schema_field_type_chk
        CHECK (data_type IN ('text', 'integer', 'decimal', 'boolean', 'date', 'datetime', 'enum')),
    CONSTRAINT inventory_schema_field_options_chk CHECK (JSON_TYPE(options) = 'ARRAY'),
    CONSTRAINT inventory_schema_field_rules_chk CHECK (JSON_TYPE(validation_rules) = 'OBJECT'),
    CONSTRAINT inventory_schema_field_order_chk CHECK (display_order >= 0),
    CONSTRAINT inventory_schema_field_enum_options_chk CHECK (data_type = 'enum' OR JSON_LENGTH(options) = 0),
    CONSTRAINT inventory_schema_field_reserved_key_chk CHECK (field_key NOT IN (
        'id', 'category_id', 'schema_version_id', 'item_code', 'name', 'description',
        'unit', 'quantity_on_hand', 'reorder_level', 'custom_attributes',
        'created_at', 'updated_at'
    )),
    CONSTRAINT inventory_schema_field_version_fk
        FOREIGN KEY (schema_version_id) REFERENCES inventory_schema_versions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELIMITER $$
DROP TRIGGER IF EXISTS inventory_schema_fields_insert_draft_only$$
CREATE TRIGGER inventory_schema_fields_insert_draft_only
BEFORE INSERT ON inventory_schema_fields
FOR EACH ROW
BEGIN
    DECLARE parent_status VARCHAR(16);
    SELECT status INTO parent_status
    FROM inventory_schema_versions
    WHERE id = NEW.schema_version_id;
    IF parent_status IS NULL OR parent_status <> 'draft' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Fields can only be added to a draft schema version';
    END IF;
END$$

DROP TRIGGER IF EXISTS inventory_schema_fields_update_draft_only$$
CREATE TRIGGER inventory_schema_fields_update_draft_only
BEFORE UPDATE ON inventory_schema_fields
FOR EACH ROW
BEGIN
    DECLARE old_status VARCHAR(16);
    DECLARE new_status VARCHAR(16);
    SELECT status INTO old_status
    FROM inventory_schema_versions
    WHERE id = OLD.schema_version_id;
    SELECT status INTO new_status
    FROM inventory_schema_versions
    WHERE id = NEW.schema_version_id;
    IF old_status IS NULL OR old_status <> 'draft'
       OR new_status IS NULL OR new_status <> 'draft' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Fields can only be changed while their schema version is a draft';
    END IF;
END$$

DROP TRIGGER IF EXISTS inventory_schema_fields_delete_draft_only$$
CREATE TRIGGER inventory_schema_fields_delete_draft_only
BEFORE DELETE ON inventory_schema_fields
FOR EACH ROW
BEGIN
    DECLARE parent_status VARCHAR(16);
    SELECT status INTO parent_status
    FROM inventory_schema_versions
    WHERE id = OLD.schema_version_id;
    IF parent_status IS NULL OR parent_status <> 'draft' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Fields can only be removed from a draft schema version';
    END IF;
END$$
DELIMITER ;

CREATE TABLE IF NOT EXISTS inventory_items (
    id                  CHAR(36) NOT NULL,
    category_id         CHAR(36) NOT NULL,
    schema_version_id   CHAR(36) NOT NULL,
    item_code           VARCHAR(80),
    name                VARCHAR(180) NOT NULL,
    description         TEXT,
    unit                VARCHAR(40) NOT NULL,
    quantity_on_hand    DECIMAL(14, 3) NOT NULL DEFAULT 0,
    reorder_level       DECIMAL(14, 3) NOT NULL DEFAULT 0,
    custom_attributes   JSON NOT NULL DEFAULT (JSON_OBJECT()),
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    created_by          CHAR(36),
    created_at          TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at          TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    UNIQUE KEY inventory_items_category_code_uq (category_id, item_code),
    UNIQUE KEY inventory_items_id_category_uq (id, category_id),
    KEY inventory_items_category_name_idx (category_id, name),
    CONSTRAINT inventory_items_quantity_chk CHECK (quantity_on_hand >= 0),
    CONSTRAINT inventory_items_reorder_level_chk CHECK (reorder_level >= 0),
    CONSTRAINT inventory_items_custom_attributes_chk CHECK (JSON_TYPE(custom_attributes) = 'OBJECT'),
    CONSTRAINT inventory_items_category_fk
        FOREIGN KEY (category_id) REFERENCES inventory_categories(id) ON DELETE RESTRICT,
    CONSTRAINT inventory_items_schema_category_fk
        FOREIGN KEY (schema_version_id, category_id)
        REFERENCES inventory_schema_versions(id, category_id) ON DELETE RESTRICT,
    CONSTRAINT inventory_items_created_by_fk
        FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELIMITER $$
DROP TRIGGER IF EXISTS inventory_items_require_active_schema_insert$$
CREATE TRIGGER inventory_items_require_active_schema_insert
BEFORE INSERT ON inventory_items
FOR EACH ROW
BEGIN
    DECLARE parent_status VARCHAR(16);
    SELECT status INTO parent_status
    FROM inventory_schema_versions
    WHERE id = NEW.schema_version_id AND category_id = NEW.category_id;
    IF parent_status IS NULL OR parent_status <> 'active' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'New inventory items must use an active schema version for their category';
    END IF;
END$$

DROP TRIGGER IF EXISTS inventory_items_require_active_schema_update$$
CREATE TRIGGER inventory_items_require_active_schema_update
BEFORE UPDATE ON inventory_items
FOR EACH ROW
BEGIN
    DECLARE parent_status VARCHAR(16);
    IF NEW.schema_version_id <> OLD.schema_version_id OR NEW.category_id <> OLD.category_id THEN
        SELECT status INTO parent_status
        FROM inventory_schema_versions
        WHERE id = NEW.schema_version_id AND category_id = NEW.category_id;
        IF parent_status IS NULL OR parent_status <> 'active' THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Items can only be moved to an active schema version for their category';
        END IF;
    END IF;
END$$
DELIMITER ;

CREATE TABLE IF NOT EXISTS inventory_transactions (
    id                  CHAR(36) NOT NULL,
    inventory_item_id   CHAR(36) NOT NULL,
    movement_type       VARCHAR(16) NOT NULL,
    quantity            DECIMAL(14, 3) NOT NULL,
    balance_after       DECIMAL(14, 3) NOT NULL,
    reference           VARCHAR(120),
    notes               TEXT,
    recorded_by         CHAR(36),
    occurred_at         TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_at          TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY inventory_transactions_item_time_idx (inventory_item_id, occurred_at),
    KEY inventory_transactions_type_time_idx (movement_type, occurred_at),
    CONSTRAINT inventory_transactions_type_chk CHECK (movement_type IN ('stock_in', 'stock_out')),
    CONSTRAINT inventory_transactions_quantity_chk CHECK (quantity > 0),
    CONSTRAINT inventory_transactions_balance_chk CHECK (balance_after >= 0),
    CONSTRAINT inventory_transactions_item_fk
        FOREIGN KEY (inventory_item_id) REFERENCES inventory_items(id) ON DELETE RESTRICT,
    CONSTRAINT inventory_transactions_recorded_by_fk
        FOREIGN KEY (recorded_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELIMITER $$
DROP TRIGGER IF EXISTS inventory_transactions_apply_movement$$
CREATE TRIGGER inventory_transactions_apply_movement
BEFORE INSERT ON inventory_transactions
FOR EACH ROW
BEGIN
    DECLARE current_balance DECIMAL(14, 3);
    DECLARE next_balance DECIMAL(14, 3);
    DECLARE item_found BOOLEAN DEFAULT TRUE;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET item_found = FALSE;

    SELECT quantity_on_hand INTO current_balance
    FROM inventory_items
    WHERE id = NEW.inventory_item_id
    FOR UPDATE;

    IF item_found = FALSE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Inventory item does not exist';
    END IF;

    IF NEW.movement_type = 'stock_in' THEN
        SET next_balance = current_balance + NEW.quantity;
    ELSE
        IF NEW.quantity > current_balance THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Insufficient stock for this stock-out';
        END IF;
        SET next_balance = current_balance - NEW.quantity;
    END IF;

    UPDATE inventory_items
    SET quantity_on_hand = next_balance
    WHERE id = NEW.inventory_item_id;

    SET NEW.balance_after = next_balance;
END$$

DROP TRIGGER IF EXISTS inventory_transactions_immutable_update$$
CREATE TRIGGER inventory_transactions_immutable_update
BEFORE UPDATE ON inventory_transactions
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Inventory transactions are immutable; record a correcting movement instead';
END$$

DROP TRIGGER IF EXISTS inventory_transactions_immutable_delete$$
CREATE TRIGGER inventory_transactions_immutable_delete
BEFORE DELETE ON inventory_transactions
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Inventory transactions are immutable; record a correcting movement instead';
END$$
DELIMITER ;

CREATE TABLE IF NOT EXISTS demand_predictions (
    id                  CHAR(36) NOT NULL,
    inventory_item_id   CHAR(36) NOT NULL,
    prediction_mode     VARCHAR(16) NOT NULL,
    predicted_quantity  DECIMAL(14, 3),
    demand_level        VARCHAR(16),
    prediction_for      DATE NOT NULL,
    model_name          VARCHAR(80) NOT NULL DEFAULT 'XGBoost',
    model_version       VARCHAR(80),
    input_features      JSON NOT NULL DEFAULT (JSON_OBJECT()),
    actual_quantity     DECIMAL(14, 3),
    generated_by        CHAR(36),
    generated_at        TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    evaluated_at        TIMESTAMP(3) NULL,
    PRIMARY KEY (id),
    KEY demand_predictions_item_date_idx (inventory_item_id, prediction_for),
    CONSTRAINT demand_predictions_mode_chk CHECK (prediction_mode IN ('classification', 'regression')),
    CONSTRAINT demand_predictions_class_chk CHECK (demand_level IS NULL OR demand_level IN ('low', 'moderate', 'high')),
    CONSTRAINT demand_predictions_quantity_chk CHECK (predicted_quantity IS NULL OR predicted_quantity >= 0),
    CONSTRAINT demand_predictions_actual_chk CHECK (actual_quantity IS NULL OR actual_quantity >= 0),
    CONSTRAINT demand_predictions_features_chk CHECK (JSON_TYPE(input_features) = 'OBJECT'),
    CONSTRAINT demand_predictions_output_chk CHECK (
        (prediction_mode = 'classification' AND demand_level IS NOT NULL AND predicted_quantity IS NULL)
        OR
        (prediction_mode = 'regression' AND predicted_quantity IS NOT NULL AND demand_level IS NULL)
    ),
    CONSTRAINT demand_predictions_item_fk
        FOREIGN KEY (inventory_item_id) REFERENCES inventory_items(id) ON DELETE RESTRICT,
    CONSTRAINT demand_predictions_generated_by_fk
        FOREIGN KEY (generated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS audit_logs (
    id              CHAR(36) NOT NULL,
    actor_id        CHAR(36),
    action          VARCHAR(80) NOT NULL,
    entity_type     VARCHAR(80) NOT NULL,
    entity_id       CHAR(36),
    before_data     JSON,
    after_data      JSON,
    occurred_at     TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY audit_logs_entity_time_idx (entity_type, entity_id, occurred_at),
    KEY audit_logs_actor_time_idx (actor_id, occurred_at),
    CONSTRAINT audit_logs_before_object_chk CHECK (before_data IS NULL OR JSON_TYPE(before_data) = 'OBJECT'),
    CONSTRAINT audit_logs_after_object_chk CHECK (after_data IS NULL OR JSON_TYPE(after_data) = 'OBJECT'),
    CONSTRAINT audit_logs_actor_fk
        FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

